	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// jsonTheme wraps a base theme with JSON-defined overrides
type jsonTheme struct {
	base         fyne.Theme
	colors       map[fyne.ThemeColorName]color.Color
	colorsDark   map[fyne.ThemeColorName]color.Color
	colorsLight  map[fyne.ThemeColorName]color.Color
	sizes        map[fyne.ThemeSizeName]float32
	fonts        map[string]fyne.Resource
	icons        map[fyne.ThemeIconName]fyne.Resource
}

// FromJSON parses a JSON string and returns a Theme with the specified overrides.
// Any values not present in the JSON fall back to the default theme.
// Returns the default theme along with an error if JSON parsing fails.
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme with the specified overrides.
// Any values not present in the JSON fall back to the default theme.
// Returns the default theme along with an error if JSON parsing fails.
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	if err := json.NewDecoder(r).Decode(&raw); err != nil {
		return DefaultTheme(), err
	}

	theme := &jsonTheme{
		base:        DefaultTheme(),
		colors:      make(map[fyne.ThemeColorName]color.Color),
		colorsDark:  make(map[fyne.ThemeColorName]color.Color),
		colorsLight: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[fyne.ThemeSizeName]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
	}

	// Parse colors
	if colors, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, value := range colors {
			if hexStr, ok := value.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.colors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse variant-specific colors
	if colorsDark, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, value := range colorsDark {
			if hexStr, ok := value.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.colorsDark[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	if colorsLight, ok := raw["Colors-light"].(map[string]interface{}); ok {
		for name, value := range colorsLight {
			if hexStr, ok := value.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.colorsLight[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse sizes
	if sizes, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, value := range sizes {
			if floatVal, ok := value.(float64); ok {
				theme.sizes[fyne.ThemeSizeName(name)] = float32(floatVal)
			}
		}
	}

	// Parse fonts
	if fonts, ok := raw["Fonts"].(map[string]interface{}); ok {
		for name, value := range fonts {
			if uriStr, ok := value.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					if res, err := storage.LoadResourceFromURI(uri); err == nil {
						theme.fonts[name] = res
					}
				}
			}
		}
	}

	// Parse icons
	if icons, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, value := range icons {
			if uriStr, ok := value.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					if res, err := storage.LoadResourceFromURI(uri); err == nil {
						theme.icons[fyne.ThemeIconName(name)] = res
					}
				}
			}
		}
	}

	return theme, nil
}

// parseHexColor parses hex color strings in various formats:
// - 3 digits: "abc" or "#abc" -> #aabbcc
// - 4 digits: "abcd" or "#abcd" -> #aabbccdd  
// - 6 digits: "a1b2c3" or "#a1b2c3" -> #a1b2c3
// - 8 digits: "a1b2c3f4" or "#a1b2c3f4" -> #a1b2c3f4
func parseHexColor(s string) (color.Color, error) {
	s = strings.TrimPrefix(s, "#")

	var r, g, b, a uint8 = 0, 0, 0, 255

	switch len(s) {
	case 3:
		// RGB shorthand: abc -> aabbcc
		vals, err := parseHexDigits(s, 3)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] * 17 // 0xa -> 0xaa
		g = vals[1] * 17
		b = vals[2] * 17
	case 4:
		// RGBA shorthand: abcd -> aabbccdd
		vals, err := parseHexDigits(s, 4)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] * 17
		g = vals[1] * 17
		b = vals[2] * 17
		a = vals[3] * 17
	case 6:
		// RRGGBB
		val, err := strconv.ParseUint(s, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", s)
		}
		r = uint8(val >> 16)
		g = uint8(val >> 8)
		b = uint8(val)
	case 8:
		// RRGGBBAA
		val, err := strconv.ParseUint(s, 16, 64)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", s)
		}
		r = uint8(val >> 24)
		g = uint8(val >> 16)
		b = uint8(val >> 8)
		a = uint8(val)
	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %s", s)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

func parseHexDigits(s string, n int) ([]uint8, error) {
	if len(s) != n {
		return nil, fmt.Errorf("expected %d hex digits, got %d", n, len(s))
	}

