package binding

import (
	"fmt"
)

// NewSprintf creates a new String binding that formats its content using the format string and the provided data sources.
// The format string follows the standard fmt.Sprintf formatting rules. The binding will automatically update whenever
// any of the source bindings change.
//
// Since: 2.5
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		return &sprintfBound{
			base:   base{},
			format: format,
			items:  nil,
		}
	}

	ret := &sprintfBound{
		base:   base{},
		format: format,
		items:  b,
	}

	// Listen to all source bindings
	listener := NewDataListener(func() {
		ret.lock.Lock()
		defer ret.lock.Unlock()
		ret.trigger()
	})

	for _, item := range b {
		item.AddListener(listener)
	}

	return ret
}

type sprintfBound struct {
	base

	format string
	items  []DataItem
}

func (s *sprintfBound) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	if len(s.items) == 0 {
		return s.format, nil
	}

	// Gather values from all bound items
	vals := make([]interface{}, len(s.items))
	for i, item := range s.items {
		switch v := item.(type) {
		case String:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			vals[i] = val
		case Int:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			vals[i] = val
		case Float:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			vals[i] = val
		case Bool:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			vals[i] = val
		case Untyped:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			vals[i] = val
		default:
			// For any other type, try to get as Untyped
			if u, ok := item.(Untyped); ok {
				val, err := u.Get()
				if err != nil {
					return "", err
				}
				vals[i] = val
			} else {
				vals[i] = fmt.Sprintf("%v", item)
			}
		}
	}

	return fmt.Sprintf(s.format, vals...), nil
}

func (s *sprintfBound) Set(string) error {
	// This is a read-only computed binding
	return nil
}

