func (s *sprintfBound) Set(val string) error {
	s.lock.Lock()
	defer s.lock.Unlock()

	if len(s.items) == 0 {
		return nil
	}

	// Parse the string using fmt.Sscanf to extract values
	vals := make([]interface{}, len(s.items))
	for i, item := range s.items {
		switch item.(type) {
		case String:
			var str string
			vals[i] = &str
		case Int:
			var num int
			vals[i] = &num
		case Float:
			var f float64
			vals[i] = &f
		case Bool:
			var b bool
			vals[i] = &b
		default:
			// For other types, try to parse as string
			var str string
			vals[i] = &str
		}
	}

	// Use Sscanf to parse the formatted string
	n, err := fmt.Sscanf(val, s.format, vals...)
	if err != nil && n == 0 {
		return err
	}

	// Update all source bindings with parsed values
	for i, item := range s.items {
		switch v := item.(type) {
		case String:
			if str, ok := vals[i].(*string); ok {
				if err := v.Set(*str); err != nil {
					return err
				}
			}
		case Int:
			if num, ok := vals[i].(*int); ok {
				if err := v.Set(*num); err != nil {
					return err
				}
			}
		case Float:
			if f, ok := vals[i].(*float64); ok {
				if err := v.Set(*f); err != nil {
					return err
				}
			}
		case Bool:
			if b, ok := vals[i].(*bool); ok {
				if err := v.Set(*b); err != nil {
					return err
				}
			}
		}
	}

	return nil
}

// StringToStringWithFormat creates a new String binding by applying a format to another String binding.
// If the format is "%s", the original binding is returned directly without wrapping.
// Otherwise, it delegates to NewSprintf to create a formatted binding.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

