package validation

import (
	"errors"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that checks if the input string matches one of the allowed strings.
// The validator will return nil if the string matches any in the allowedStrings slice, otherwise returns an error.
//
// Since: 2.5
func NewAllStrings(allowedStrings []string) fyne.StringValidator {
	return func(text string) error {
		for _, allowed := range allowedStrings {
			if text == allowed {
				return nil
			}
		}
		return errors.New("input does not match any allowed strings")
	}
}

